local bySpell, byEnchant = {}, {}
for familyId, fam in pairs(families) do
    for rank, entry in pairs(fam.ranks) do
        bySpell[entry.spellId] = { familyId = familyId, rank = rank }
        byEnchant[entry.enchantId] = { familyId = familyId, rank = rank }
    end
end

ProjectEbonhold.AffixDatabase = {
    families = families,
    bySpell = bySpell,
    byEnchant = byEnchant,
    familyCount = 268,
    ranks = 5,
    roman = { "I", "II", "III", "IV", "V" },
    categoryNames = { [1] = "Offensive", [2] = "Defensive", [3] = "Resource", [4] = "Utility", [5] = "Mobility" },
}

-- Entree statique d'un sort appris (nil si le fichier est plus vieux que le serveur).
function ProjectEbonhold.AffixDatabase.GetBySpell(spellId)
    local ref = bySpell[spellId]
    if not ref then return nil end
    local fam = families[ref.familyId]
    return fam, fam.ranks[ref.rank], ref.familyId, ref.rank
end

function ProjectEbonhold.AffixDatabase.GetByEnchant(enchantId)
    local ref = byEnchant[enchantId]
    if not ref then return nil end
    local fam = families[ref.familyId]
    return fam, fam.ranks[ref.rank], ref.familyId, ref.rank
end
